def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    day = day_context['day']
    supply = float(day_context['supply'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0

    alive_opponents = []
    prev_bids = []
    rich_pressure = 0
    desperate_count = 0

    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)
            prev = opp.get('previous_trace', {})
            bid = prev.get('bid') if prev else None
            if bid is not None:
                prev_bids.append(float(bid))
                if bid >= 80:
                    rich_pressure += 1
            if opp.get('hp', 0) <= 3 or opp.get('no_water_days', 0) >= 1:
                desperate_count += 1

    if not alive_opponents:
        return min(budget, 18.0)

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    supply_tight = supply <= 17
    supply_loose = supply >= 22

    danger = 0
    if hp <= 2:
        danger += 4
    elif hp <= 4:
        danger += 2
    if no_water_days >= 1:
        danger += 3
    if supply_tight:
        danger += 2
    elif supply_loose:
        danger -= 1
    if highest_prev >= 100:
        danger += 2
    elif highest_prev >= 80:
        danger += 1
    if desperate_count >= 2:
        danger += 1

    if danger >= 7:
        target = max(95.0, highest_prev + 3.0)
    elif danger >= 5:
        target = max(78.0, avg_prev + 4.0, highest_prev * 0.92)
    elif danger >= 3:
        target = max(52.0, avg_prev * 0.72)
        if highest_prev >= 90:
            target = min(target, 60.0)
    else:
        if supply_loose:
            target = 18.0
        else:
            target = 28.0
        if highest_prev >= 95:
            target = min(target, 22.0)

    if day >= 8:
        target += 8.0
    elif day >= 6:
        target += 4.0

    reserve_floor = 0.0
    if hp > 4 and no_water_days == 0:
        reserve_floor = DAILY_SALARY * 1.2
    elif hp > 2:
        reserve_floor = DAILY_SALARY * 0.7

    spendable = max(0.0, budget - reserve_floor)
    if danger >= 5:
        cap = budget
    else:
        cap = max(0.0, min(budget, spendable + DAILY_SALARY * 0.35))

    bid = min(target, cap)

    if hp <= 2 and budget >= 60:
        bid = max(bid, min(budget, highest_prev + 5.0 if highest_prev > 0 else 63.0))

    if bid < 0:
        bid = 0.0
    if bid > budget:
        bid = budget

    return bid

def get_bid(day_context, my_status, opponents_status):
    DAILY_SALARY = 90
    WATER_REQ = 9
    supply = day_context['supply']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    if not alive_opponents:
        # no competition, bid low
        return min(budget, DAILY_SALARY * 0.3)

    # Collect yesterday's bids from opponents
    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    if yesterday_bids:
        max_prev_bid = max(yesterday_bids)
        # If opponents were very aggressive yesterday, they might be low on budget today
        if max_prev_bid > DAILY_SALARY * 0.85:
            if hp > 3:
                # I can save money
                return min(budget, DAILY_SALARY * 0.35)
            else:
                # I need water, but opponents may be weak
                return min(budget, DAILY_SALARY * 0.8)
        else:
            # opponents were moderate, bid slightly above their max if needed
            base = max(DAILY_SALARY * 0.4, max_prev_bid + 1.5)
            if hp <= 2:
                base = max(base, DAILY_SALARY * 0.85)
            return min(budget, base)
    else:
        # No yesterday traces, rely on hp
        if hp <= 2:
            return min(budget, DAILY_SALARY * 0.9)
        elif hp <= 5:
            return min(budget, DAILY_SALARY * 0.6)
        else:
            return min(budget, DAILY_SALARY * 0.4)

